/** Synchronous crypto adapter for the same TDS1 container the browser reads. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    decryptSaveSync
 * depends    src/save-decoder/encrypted
 * used by    src/calculators/specs.generated, src/node/decode-save
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { createDecipheriv, createHmac, timingSafeEqual } from 'node:crypto'
import { encryptedSaveParts, isEncryptedSave, saveEncryptionKeys, unmaskSave } from '../save-decoder/encrypted'

export function decryptSaveSync(bytes: Uint8Array): Uint8Array {
  if (!isEncryptedSave(bytes)) return bytes
  const parts = encryptedSaveParts(bytes)
  const keys = saveEncryptionKeys()
  const expected = createHmac('sha256', keys.authentication).update(parts.authenticated).digest()
  if (!timingSafeEqual(parts.mac, expected)) {
    throw new Error('This encrypted save failed its integrity check. Copy it again and retry.')
  }
  const decipher = createDecipheriv('aes-256-cbc', keys.encryption, parts.iv)
  let plaintext: Uint8Array
  try {
    plaintext = Buffer.concat([decipher.update(parts.ciphertext), decipher.final()])
  }
  catch {
    throw new Error('This encrypted save could not be decrypted.')
  }
  return unmaskSave(plaintext)
}
